/* ---------------------------------------------------------------------------
   Sound Engine (Web Audio API — synthesised, no external libraries)
   AudioContext is created lazily on the first play call (user-gesture guard)
   so it satisfies browser autoplay policy.
   --------------------------------------------------------------------------- */
const SoundEngine = (() => {
  let _ctx   = null;
  let _muted = false;

  function _ensureContext() {
    if (!_ctx) {
      const AC = (typeof window !== 'undefined') &&
                 (window.AudioContext || window.webkitAudioContext);
      if (!AC) return null;
      _ctx = new AC();
    }
    if (_ctx.state === 'suspended') { _ctx.resume(); }
    return _ctx;
  }

  function _playNote(ctx, frequency, type, startTime, duration, gainPeak) {
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, startTime);
    gain.gain.setValueAtTime(0, startTime);
    gain.gain.linearRampToValueAtTime(gainPeak, startTime + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.001, startTime + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(startTime);
    osc.stop(startTime + duration + 0.01);
  }

  function playClick() {
    if (_muted) return;
    const ctx = _ensureContext(); if (!ctx) return;
    const now = ctx.currentTime;
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(600, now);
    osc.frequency.exponentialRampToValueAtTime(150, now + 0.08);
    gain.gain.setValueAtTime(0.3, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
    osc.connect(gain); gain.connect(ctx.destination);
    osc.start(now); osc.stop(now + 0.09);
  }

  function playWin() {
    if (_muted) return;
    const ctx = _ensureContext(); if (!ctx) return;
    const now   = ctx.currentTime;
    const notes = [523, 659, 784, 1047];
    notes.forEach((f, i) => _playNote(ctx, f, 'sine', now + i * 0.12, 0.15, 0.25));
  }

  function playDraw() {
    if (_muted) return;
    const ctx = _ensureContext(); if (!ctx) return;
    const now   = ctx.currentTime;
    const notes = [494, 392, 311, 247];
    notes.forEach((f, i) => _playNote(ctx, f, 'sawtooth', now + i * 0.12, 0.18, 0.18));
  }

  function playNewGame() {
    if (_muted) return;
    const ctx = _ensureContext(); if (!ctx) return;
    const now  = ctx.currentTime;
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(800, now);
    osc.frequency.exponentialRampToValueAtTime(200, now + 0.3);
    gain.gain.setValueAtTime(0.15, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
    osc.connect(gain); gain.connect(ctx.destination);
    osc.start(now); osc.stop(now + 0.31);
  }

  function toggleMute() { _muted = !_muted; return _muted; }
  function isMuted()    { return _muted; }
  function _hasContext() { return _ctx !== null; }

  return { playClick, playWin, playDraw, playNewGame, toggleMute, isMuted, _hasContext };
})();
```

